"use strict";(self.webpackChunkdocusaurus_wiki=self.webpackChunkdocusaurus_wiki||[]).push([[7358],{1372:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>o,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>l,toc:()=>p});var u=s(7462),a=(s(7294),s(3905)),n=(s(6256),s(3767));const i={title:"Ssangsue"},r=void 0,l={unversionedId:"roles/ssangsue",id:"roles/ssangsue",title:"Ssangsue",description:"Description",source:"@site/docs/roles/ssangsue.mdx",sourceDirName:"roles",slug:"/roles/ssangsue",permalink:"/botc-wiki/docs/roles/ssangsue",draft:!1,tags:[],version:"current",frontMatter:{title:"Ssangsue"}},o={},p=[{value:"Description",id:"description",level:3},{value:"Exemples",id:"exemples",level:3},{value:"M\xe9caniques et conseils",id:"m\xe9caniques-et-conseils",level:3},{value:"Combattre la Ssangsue",id:"combattre-la-ssangsue",level:3},{value:"Comment conter",id:"comment-conter",level:3}],m={toc:p};function c(e){let{components:t,...s}=e;return(0,a.kt)("wrapper",(0,u.Z)({},m,s,{components:t,mdxType:"MDXLayout"}),(0,a.kt)(n.Z,{SSANGSUE:!0,header:!0,mdxType:"Role"}),(0,a.kt)("h3",{id:"description"},"Description"),(0,a.kt)("p",null,"Chaque nuit*, choisissez un joueur\xa0: il meurt. Vous commencez par choisir un joueur vivant\xa0: il est empoisonn\xe9 et vous mourez si et seulement s'il est mort."),(0,a.kt)("p",null,"La Ssangsue vit si son h\xf4te vit et meurt si son h\xf4te meurt."),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"La premi\xe8re nuit, la Ssangsue choisis un joueur qui est empoisonn\xe9 pour le reste de la partie.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si ce joueur est en vie, la Ssangsue ne peut pas mourir. Si la Ssangsue est ex\xe9cut\xe9e, le Conteur annonce au village que le joueur ne meurt pas mais sans dire pourquoi.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si le joueur que la Ssangsue a choisi meurt, la Ssangsue meurt aussi. Si cela signifie qu\u2019il ne reste qu\u2019un ou deux joueurs apr\xe8s, le village gagne toujours car le D\xe9mon est mort.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"A partir de la deuxi\xe8me nuit et les nuits suivantes, les joueurs que la Ssangsue attaque meurent mais ne sont pas empoisonn\xe9es.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si la Ssangsue est cr\xe9\xe9e en milieu de partie, elle empoisonne un joueur cette nuit. Elle doit choisir un joueur vivant."))),(0,a.kt)("h3",{id:"exemples"},"Exemples"),(0,a.kt)("blockquote",null,(0,a.kt)("p",{parentName:"blockquote"},"La Ssangsue empoisonne le ",(0,a.kt)(n.Z,{NOBLE:!0,mdxType:"Role"}),". Le ",(0,a.kt)(n.Z,{NOBLE:!0,mdxType:"Role"})," apprend une fausse information. La Ssangsue est ex\xe9cut\xe9e mais ne meurt pas. Le jour suivant, le ",(0,a.kt)(n.Z,{NOBLE:!0,mdxType:"Role"})," est ex\xe9cut\xe9. Le ",(0,a.kt)(n.Z,{NOBLE:!0,mdxType:"Role"})," et la Ssangsue meurent. Le village gagne.")),(0,a.kt)("blockquote",null,(0,a.kt)("p",{parentName:"blockquote"},"La Ssangsue empoisonne le ",(0,a.kt)(n.Z,{FERMIERE:!0,mdxType:"Role"}),". La Ssangsue est rendue ivre par la ",(0,a.kt)(n.Z,{COURTISAN:!0,mdxType:"Role"}),". Le ",(0,a.kt)(n.Z,{FERMIERE:!0,mdxType:"Role"})," empoisonn\xe9 meurt et la partie continue car la Ssangsue est aussi ivre. La Ssangsue ivre est ex\xe9cut\xe9e et meurt. Le village gagne.")),(0,a.kt)("h3",{id:"m\xe9caniques-et-conseils"},"M\xe9caniques et conseils"),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Communiquez avec vos Sbires aussi t\xf4t que possible et dites-leur qui vous avez empoisonn\xe9. L\u2019int\xe9gralit\xe9 des mal\xe9fiques a besoin de bien collaborer depuis le tout d\xe9but pour garder le joueur en vie. Disons que vous avez fait du ",(0,a.kt)(n.Z,{PREDICATEUR:!0,mdxType:"Role"})," votre h\xf4te en l\u2019empoisonnant. Non seulement, vous pouvez l\u2019ignorer comme menace puisqu\u2019il ne peut plus affecter aucun de vos Sbires mais vous avez activement besoin de le garder en vie dans le trio final.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Empoisonnez un de vos voisins car vous pourrez alors gardez vote h\xf4te sous votre contr\xf4le. Vous pouvez savoir quelle est son information empoisonn\xe9e et manipuler la partie pour que cette info semble l\xe9gitime ce qui ne lui fera pas penser qu\u2019il est empoisonn\xe9. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Empoisonnez quelqu\u2019un de l\u2019autre c\xf4t\xe9 du cercle pour attirer l\u2019attention aussi loin de vous que possible.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Evitez d\u2019\xeatre ex\xe9cut\xe9. M\xeame si vous ne pouvez pas mourir par ex\xe9cution, si le village apprend qui est le D\xe9mon, cela peut \xeatre une information suffisante pour gagner la partie. Une fois que les joueurs savent que le D\xe9mon est une Ssangsue, il est probable qu\u2019ils vous excluent des discussions pour essayer de trouver quel joueur gentil est l\u2019h\xf4te.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Qui vous choisissez comme h\xf4te peut avoir un gros impact sur la partie. C\u2019est un choix que vous devez faire \xe0 l\u2019aveugle. Si vous choisissez un r\xf4le qui n\u2019a qu\u2019une information la premi\xe8re nuit, \xe7a peut \xeatre difficile pour lui de savoir qu\u2019il est empoisonn\xe9, ce qui vous rend la t\xe2che de cacher l\u2019h\xf4te plus facile. Toutefois, il est plus probable qu\u2019il soit d\u2019accord avec son ex\xe9cution pour tout un tas de raisons puisqu\u2019il n\u2019a plus de capacit\xe9 pour la partie. Si le ",(0,a.kt)(n.Z,{NOBLE:!0,mdxType:"Role"})," est l\u2019h\xf4te et qu\u2019il y a beaucoup de r\xe9sistance pour l\u2019ex\xe9cuter alors qu\u2019il est d\u2019accord pour cela, \xe7a peut fortement induire qu\u2019il est l\u2019h\xf4te. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"S\u2019il y a juste 3 joueurs en vie, vous faire ex\xe9cuter est une strat\xe9gie prudente. Car si l\u2019h\xf4te est toujours en vie, vous serez ex\xe9cut\xe9 et ne mourez pas. Ensuite, on passe \xe0 la nuit avec toujours 3 joueurs en vie et vous pouvez tuer le dernier joueur qui n\u2019est pas l\u2019h\xf4te. Notez bien qu\u2019il est important dans cette situation de ne pas tuer l\u2019h\xf4te car sinon vous allez mourir imm\xe9diatement. Cela va cr\xe9er une \xe9galit\xe9 ce qui signifie une victoire du village. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si, pour une quelconque raison, le village semble chercher un h\xf4te \xe0 ex\xe9cuter, vous pourriez avoir besoin de rediriger l\u2019attention ailleurs. Si vous faites beaucoup de bruits pour NE PAS ex\xe9cuter un joueur sp\xe9cifiquement, \xe7a peut paraitre tr\xe8s suspicieux. A la place, vous pouvez peut-\xeatre d\xe9signer quelqu\u2019un d\u2019autre comme une grosse cible m\xeame si cela signifie de jeter un de vos Sbires sous le bus. La meilleure strat\xe9gie est d\u2019arriver au trio final sans avoir beaucoup d\u2019attention sur l\u2019h\xf4te. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Dans une partie avec un D\xe9mon \xab classique \xbb, la priorit\xe9 est de prot\xe9ger le D\xe9mon de la mort. Dans une partie avec une Ssangsue, la priorit\xe9 est de cr\xe9er autant de d\xe9sinformation que possible pour cacher l\u2019h\xf4te. De cette fa\xe7on, m\xeame si une personne doute de ses informations ce n\u2019est qu\u2019une mauvaise source d\u2019information parmi d\u2019autres.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"La Ssangsue peut \xeatre particuli\xe8rement difficile \xe0 jouer car dans les faits, un des membres de votre \xab \xe9quipe \xbb est gentil. Il n\u2019est pas align\xe9 avec vous et vous n\u2019avez pas de contr\xf4le sur son empoisonnement. Il est parfaitement possible de sugg\xe9rer au Conteur de informations \xe0 donner \xe0 l\u2019h\xf4te empoisonn\xe9 mais le Conteur n\u2019est pas oblig\xe9 de suivre votre requ\xeate.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si les mal\xe9fiques ont la main mise sur la fin de partie, alors le Conteur pourrait rendre l\u2019empoisonnement de l\u2019h\xf4te tr\xe8s \xe9vident comme une compensation, en particulier si pour certaines raisons, il est pass\xe9 sous le radar toute la partie et que le village n\u2019a pas d\xe9couvert que c\u2019est une partie avec une Ssangsue."))),(0,a.kt)("h3",{id:"combattre-la-ssangsue"},"Combattre la Ssangsue"),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"D\xe9terminez si une Ssangsue est en jeu ou pas. Cette information d\xe9termine votre objectif de la partie puisque tant que vous ne l\u2019avez pas devin\xe9, vous ne saurez pas quel joueur ex\xe9cuter. Une fois que vous savez que c\u2019est une partie avec une Ssangsue alors la cl\xe9 est de trouver et tuer l\u2019h\xf4te \xe0 la place.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Trouver le joueur empoisonn\xe9. Si tous les joueurs gentils qui pensent \xeatre potentiellement empoisonn\xe9s le disent au village, alors il pourrait deviner qui pourrait \xeatre l\u2019h\xf4te de la Ssangsue."),(0,a.kt)("ul",{parentName:"li"},(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si quelqu\u2019un a des infos incoh\xe9rentes : ex\xe9cutez-le. Il y a des chances que \xe7a soit un h\xf4te de la Ssangsue ou peut \xeatre juste un Sbire qui diffuse de fausses informations. Gagnant-gagnant !")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si vous pensez avoir de fausses informations : soyez volontaires pour \xeatre ex\xe9cut\xe9s et retirez-vous de l\u2019\xe9quation.")))),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Utilisez les r\xf4les \xe0 informations pour v\xe9rifier les informations des autres joueurs pour r\xe9duire la liste des candidats possiblement empoisonn\xe9s. Rappelez-vous que seul un joueur peut \xeatre l\u2019h\xf4te de la Ssangsue et qu\u2019il ne peut pas bouger. Si vous pouvez v\xe9rifier qu\u2019un joueur est sobre et sain, il ne peut pas \xeatre l\u2019h\xf4te de la Ssangsue.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si vous n\u2019avez pas de bons candidats possiblement h\xf4tes en vous basant sur les informations disponibles, cherchez des joueurs qui semblent \xe9tonnement survivre. Voici une liste des possibilit\xe9s d\u2019h\xf4te qui passe sous le radar :"),(0,a.kt)("ul",{parentName:"li"},(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Un joueur gentil confirm\xe9 ou une cible de haute priorit\xe9 publique qui survit toute la partie comme un ",(0,a.kt)(n.Z,{AERONAUTE:!0,mdxType:"Role"})," qui se serait d\xe9voil\xe9 publiquement.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Un r\xf4le d\u2019information de premi\xe8re nuit qui semble \xeatre maintenu en vie comme un ",(0,a.kt)(n.Z,{HORLOGER:!0,mdxType:"Role"})," qui n\u2019a pas fait grand-chose depuis le d\xe9but et qui est volontaire pour \xeatre ex\xe9cut\xe9.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Une capacit\xe9 \xe0 usage unique qui a \xe9t\xe9 utilis\xe9e comme un ",(0,a.kt)(n.Z,{PECHEUR:!0,mdxType:"Role"})," qui a suivi son conseil mais qui ne semble pas faire autre chose.")))),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"N\u2019oubliez pas de trouver qui sont les mal\xe9fiques ! Bien que \xe7a ne vous fasse directement gagner la partie, ex\xe9cuter le D\xe9mon est toujours une bonne information. Plus important, il est tr\xe8s improbable que le D\xe9mon choisisse un de ses Sbires comme h\xf4te donc vous pouvez probablement les \xe9liminer comme h\xf4tes potentiels.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Puisque la probabilit\xe9 de trouver que c\u2019est une partie avec une Ssangsue est plus haute que de ne pas le trouver, si vous arrivez au jour final et que vous n\u2019\xeates pas s\xfbrs, il est habituellement plus prudent de supposer que ce n\u2019est pas une partie avec une Ssangsue."))),(0,a.kt)("h3",{id:"comment-conter"},"Comment conter"),(0,a.kt)("p",null,'Durant la premi\xe8re nuit, r\xe9veillez la Ssangsue. Elle d\xe9signe n\u2019importe quel joueur. Ce joueur est empoisonn\xe9, marquez-le avec le jeton de rappel "Empoisonn\xe9". Rendormez la Ssangsue.'),(0,a.kt)("p",null,'Chaque nuit, sauf la premi\xe8re, r\xe9veillez la Ssangsue. Elle d\xe9signe n\u2019importe quel joueur. Ce joueur meurt. Marquez-le avec le jeton de rappel " Mort ". Rendormez la Ssangsue.'),(0,a.kt)("p",null,'Si la Ssangsue devrait mourir mais que le joueur marqu\xe9 par le jeton de rappel "Empoisonn\xe9" de la Ssangsue est vivant, la Ssangsue ne meurt pas. Si le joueur maqu\xe9 par le jeton de rappel "Empoisonn\xe9" de la Ssangsue est mort, la Ssangsue meurt et le village gagne.'),(0,a.kt)("p",null,(0,a.kt)("em",{parentName:"p"},"En donnant de fausses informations \xe0 un joueur gentil empoisonn\xe9 par la Ssangsue, assurez-vous que cette information ait l\u2019air vraie. Si le joueur gentil croit qu\u2019elle est fausse, il va rapidement essayer de se faire ex\xe9cuter et gagner la partie.")),(0,a.kt)("p",null,(0,a.kt)("strong",{parentName:"p"},"Compl\xe9ments Conteur")),(0,a.kt)("p",null,"Si la Ssangsue est ivre ou empoisonn\xe9e, l'h\xf4te est sobre. Si l'h\xf4te meurt pendant ce temps, la Ssangsue n'est pas affect\xe9e. Si la Ssangsue elle-m\xeame meurt en \xe9tant ivre ou empoisonn\xe9e, elle meurt car sa capacit\xe9 ne l'empeche pas de mourir en \xe9tant ivre ou empoisonn\xe9e. Si l'h\xf4te est ivre ou empoisonn\xe9, cela n'affecte pas la Ssangsue."),(0,a.kt)("p",null,"La Ssangsue est toujours consid\xe9r\xe9e comme D\xe9mon et son h\xf4te est toujours consid\xe9r\xe9 comme son type de d\xe9part. Le choix d'h\xf4te n'affecte pas comment est consid\xe9r\xe9 le joueur. Notez bien que l'h\xf4te peut \xeatre de n'importe quel joueur vivant quelque soit son type."),(0,a.kt)("p",null,"Si une nouvelle Ssangsue est cr\xe9e apr\xe8s la premi\xe8re nuit, elle est r\xe9veill\xe9e imm\xe9diatement apr\xe8s \xeatre devenue Ssangsue pour choisir son h\xf4te. Elle est ensuite rendormie puis r\xe9veillez \xe0 nouveau au tour de jeu normal de la Ssangsue pour attaquer le cas \xe9ch\xe9ant."),(0,a.kt)("p",null,(0,a.kt)("strong",{parentName:"p"},"Interactions notables")),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Voyageurs : Peuvent \xeatre choisis comme h\xf4te mais ce n\u2019est pas probablement pas recommand\xe9 car si le Voyageur s\u2019en va, il meurt et donc la Ssangsue meurt aussi. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{CHARMEUR_DE_SERPENT:!0,mdxType:"Role"})," : Si le Charmeur de serpent vise la Ssangsue, elle choisit un nouvel h\xf4te quand elle devient la Ssangsue."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{EXORCISTE:!0,mdxType:"Role"})," : Si la Ssangsue est exorcis\xe9e apr\xe8s sa premi\xe8re nuit, elle ne se r\xe9veille pas mais son h\xf4te reste empoisonn\xe9 et la Ssangsue ne peut pas mourir \xe0 moins que l\u2019h\xf4te meurt."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{FOU_DU_ROI:!0,mdxType:"Role"})," / ",(0,a.kt)(n.Z,{TISANIERE:!0,mdxType:"Role"})," / ",(0,a.kt)(n.Z,{MARIN:!0,mdxType:"Role"})," / ",(0,a.kt)(n.Z,{PACIFISTE:!0,mdxType:"Role"})," / ",(0,a.kt)(n.Z,{AVOCAT_DU_DIABLE:!0,mdxType:"Role"})," : Il n\u2019y a pas de diff\xe9rence entre l\u2019ex\xe9cution de la Ssangsue et une de ses capacit\xe9s qui prot\xe8ge de la mort par ex\xe9cution. Toutes ont pour r\xe9sultat un joueur qui est ex\xe9cut\xe9 mais qui ne meurt pas."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{MAIRE:!0,mdxType:"Role"})," : Le Maire ne peut pas faire rebondir le choix de l\u2019h\xf4te de la Ssangsue. Une fois empoisonn\xe9, il n\u2019a pas de capacit\xe9 et donc ne peut pas gagner dans le trio final et il ne peut pas non plus faire rebondir une attaque de D\xe9mon la nuit."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{MERCENAIRE:!0,mdxType:"Role"}),' : Jinx - "Si le Mercenaire tire sur l\u2019h\xf4te de la Ssangsue, l\u2019h\xf4te meurt (ce qui entra\xeene bien s\xfbr la mort de la Ssangsue si elle est sobre et saine.)"'),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{MOINE:!0,mdxType:"Role"})," : Si l'h\xf4te est choisi par le Moine, il devient sobre pour cette nuit."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{PROFESSEUR:!0,mdxType:"Role"})," : Si l\u2019h\xf4te de la Ssangsue meurt, la Ssangsue meurt aussi mais si l\u2019h\xf4te est ressuscit\xe9, la Ssangsue n\u2019est pas ressuscit\xe9e."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{SOLDAT:!0,mdxType:"Role"})," : S'il est choisi comme h\xf4te, il n'est pas empoisonn\xe9 mais s'il meurt, quelle que soit la raison (execution, Lycanthrope,etc..) alors la Ssangsue meurt aussi."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{BRUTE:!0,mdxType:"Role"})," : Si s\xe9lectionn\xe9 comme h\xf4te, rend la sansgue ivre jusqu'au cr\xe9puscule et la Brute passe mal\xe9fique. Si la Brute est alors ex\xe9cut\xe9e ce jour, la Ssangsue ne meurt pas car elle est ivre. La Brute est sobre pour toute la partie mais si la Brute meurt apr\xe8s ce premier jour, la Ssangsue meurt aussi."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{HERETIQUE:!0,mdxType:"Role"}),' : Jinx : "Seul un des r\xf4les jinx\xe9s peut \xeatre en jeu."'),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{LUNATIQUE:!0,mdxType:"Role"})," : Si le Lunatique pense \xeatre une Ssangsue, le v\xe9ritable D\xe9mon est inform\xe9 du choix de l'h\xf4te la premi\xe8re nuit mais il n'y a pas de diff\xe9rence visible avec, par exemple, un Lunatique qui pense \xeatre Pukka et qui choisir une cible la premi\xe8re nuit. Le D\xe9mon ne saura pas la diff\xe9rence."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{ASSASSIN:!0,mdxType:"Role"})," : Peut tuer la Ssangsue."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{CONSPIRATEUR:!0,mdxType:"Role"})," : Jinx: \xab Si le Conspirateur est en vie et que l\u2019h\xf4te de la Ssangsue est ex\xe9cut\xe9, la Ssangsue vie mais perd sa capacit\xe9. \xbb"),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{GUENAUDE:!0,mdxType:"Role"})," : Si un nouveau D\xe9mon est cr\xe9\xe9, l\u2019h\xf4te doit mourir pour que la Ssangsue soit tu\xe9e. La Guenaude ne peut pas outrepasser la capacit\xe9 de la Ssangsue."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{BARISTA:!0,mdxType:"Role"})," : Si le Barista fait jouer la Ssangsue deux fois en dehors de la premi\xe8re nuit, la Ssangsue tue deux fois. Si c\u2019est lors de la premi\xe8re nuit, elle choisit deux joueurs, le deux sont empoisonn\xe9s. Tous les deux doivent mourir pour que la Ssangsue meure."),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)(n.Z,{GALANTE:!0,mdxType:"Role"})," / ",(0,a.kt)(n.Z,{GANGSTER:!0,mdxType:"Role"})," / ",(0,a.kt)(n.Z,{VENGEUR:!0,mdxType:"Role"})," : Ne peuvent pas tuer la Ssangsue.")))}c.isMDXComponent=!0}}]);